parameters.jsCode:
const original = $('Build Conversation Context').first().json;
const extracted = $input.first().json || {};

return [{
  json: {
    ...original,
    attachment_text: extracted.attachment_text || '',
    attachment_summary: extracted.attachment_summary || '',
    attachment_extraction_method: extracted.extraction_method || 'none'
  }
}];

const history = Array.isArray($json.history) ? $json.history : [];
const currentMessage = ($json.message || '').toLowerCase().trim();

// STRICTLY only previous USER messages
const userMessages = history
  .filter(item => item.role === 'user')
  .map(item => item.user_query || item.user_message || item.message || item.text || '')
  .filter(Boolean)
  .filter(msg => msg.toLowerCase().trim() !== currentMessage);

const lastUserMessage = userMessages[userMessages.length - 1] || '';

function extractTopic(text) {
  const stopWords = [
    'did','i','ask','anything','something','about','or','related','to','what','was',
    'the','thing','earlier','before','previously','previous','my','issue'
  ];
  return text
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(word => word && !stopWords.includes(word));
}

let answer = "I could not find anything earlier.";

if (
  currentMessage.includes('what did i ask') ||
  currentMessage.includes('what was my issue') ||
  currentMessage.includes('what was the thing i asked') ||
  currentMessage.includes('earlier') ||
  currentMessage.includes('previous')
) {
  if (lastUserMessage) {
    answer = `You earlier asked: "${lastUserMessage}"`;
  }
} else if (
  currentMessage.includes('did i ask') ||
  currentMessage.includes('related to')
) {
  const topicWords = extractTopic(currentMessage);

  const matchedMessage = userMessages.find(msg =>
    topicWords.some(word => msg.toLowerCase().includes(word))
  );

  if (matchedMessage) {
    answer = `Yes, you earlier asked: "${matchedMessage}"`;
  } else {
    answer = `No, I could not find an earlier user message about that.`;
  }
}

return [{
  json: {
    ...$json,
    answer
  }
}];

const userMessage = $json.message || '';
const assistantMessage = $json.final_response_text || '';
const attachmentSummary = $json.attachment_summary || '';

return [{
  json: {
    conversationId: $json.conversationId || '',
    user_message: userMessage,
    assistant_message: assistantMessage,
    intent: 'attachment_info_request',
    matched_issue: 'attachment_info_request',
    issue_summary: assistantMessage || attachmentSummary || userMessage,
    user_query: userMessage,
    attachment_summary: attachmentSummary,
    ticket_id: null,
    messageId: $json.messageId || ''
  }
}];

const attachmentSummary = ($json.attachment_summary || '').trim();
const attachmentText = ($json.attachment_text || '').trim();
const content = (attachmentSummary || attachmentText).toLowerCase();

// ---- REJECT-KNOWN-BAD approach ----
// Only reject if the content clearly identifies as a known non-StrideOne app.
// This handles cropped screenshots that won't have the sidebar or STRIDE logo.

// Known non-platform app signatures (branding, URLs, unique UI text)
const nonPlatformSignatures = [
  // Food delivery
  'zomato', 'swiggy', 'uber eats', 'doordash',
  // E-commerce
  'amazon.com', 'amazon.in', 'flipkart', 'myntra', 'meesho', 'ajio',
  // Ride hailing
  'uber.com', 'ola cabs', 'rapido',
  // Social media
  'instagram', 'facebook.com', 'twitter.com', 'x.com', 'snapchat', 'tiktok', 'youtube.com',
  // Messaging
  'whatsapp', 'telegram', 'signal',
  // Entertainment
  'netflix', 'spotify', 'hotstar', 'prime video',
  // Consumer payments (not lending)
  'paytm mall', 'phonepe store', 'google pay rewards',
  // Gaming
  'play store', 'app store', 'game over', 'level up',
  // Device OS screens
  'enable device location', 'enable location services', 'location permission',
  'allow .* to access your location', 'turn on gps',
  'battery saver', 'do not disturb', 'airplane mode',
  'notification settings', 'app permissions'
];

// Check if content matches any known non-platform signature
const isKnownNonPlatform = nonPlatformSignatures.some(sig => {
  if (sig.includes('.*')) {
    return new RegExp(sig, 'i').test(content);
  }
  return content.includes(sig);
});

// Also quick-confirm: if any StrideOne identifier is present, never reject
const strideoneConfirmers = [
  'stride', 'strideone', 'jarvis-new.strideone',
  'carma dashboard', 'farmer dashboard', 'counterparty', 'task inbox',
  'prescreening', 'lender platform', 'case allocation', 'collection agencies',
  'stride rating', 'total aum', 'stop effort', 'sanctioned amount',
  'coapplicant', 'co-applicant', 'data entry in progress',
  'sales tasks', 'credit/cpa', 'flexy dial', 'call batches',
  'cam approval', 'cad l1', 'vendor limit', 'agreement signing',
  'application id', 'ckyc', 'cibil', 'penny drop'
];
const hasStrideoneSignal = strideoneConfirmers.some(kw => content.includes(kw));

// Decision: reject ONLY if known non-platform AND no StrideOne signal
const shouldReject = isKnownNonPlatform && !hasStrideoneSignal;

let response = '';

if (!attachmentSummary && !attachmentText) {
  response = 'I could not extract readable content from the attachment. Please upload a clearer image or PDF.';
} else if (shouldReject) {
  response = 'This screenshot does not appear to be from our platform. I can only help with issues related to the StrideOne lending and loan management system. Please upload a screenshot from our platform, or describe your issue in text so I can assist you.';
} else {
  response = attachmentSummary || attachmentText.slice(0, 1500);
}

return [{
  json: {
    ...$json,
    final_response_text: response,
    final_category: 'attachment_info_request',
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category: 'attachment_info_request',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

const llmOutput = $input.first().json;
const original = $('Prepare attachment info Memory1').first().json;

const raw =
  llmOutput?.content?.parts?.[0]?.text ||
  llmOutput?.text ||
  llmOutput?.output ||
  '';

let cleaned = String(raw)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    response: 'I could not clearly find that information in the attachment.',
    extracted_value: null,
    field_name: null
  };
}

return [{
  json: {
    conversationId: original.conversationId || '',
    user_message: original.user_message || '',
    assistant_message: parsed.response || 'I could not clearly find that information in the attachment.',
    intent: 'attachment_info_request',
    matched_issue: 'attachment_info_request',
    issue_summary: original.attachment_summary || original.user_message || '',
    user_query: original.user_message || '',
    attachment_summary: original.attachment_summary || '',
    ticket_id: null,
    messageId: original.messageId || '',
    final_response_text: parsed.response || 'I could not clearly find that information in the attachment.',
    extracted_value: parsed.extracted_value || null,
    field_name: parsed.field_name || null
  }
}];

const message = ($json.message || '').toLowerCase().trim();
const history = Array.isArray($json.history) ? $json.history : [];
const hasNewAttachment = !!($json.hasAttachment && $json.file_url);

function detectRequestedField(text) {
  if (/app(lication)? id|application number|app number/i.test(text)) return 'application id';
  if (/loan number|loan id/i.test(text)) return 'loan number';
  if (/status/i.test(text)) return 'status';
  if (/ifsc/i.test(text)) return 'ifsc';
  if (/bank name|bank/i.test(text)) return 'bank name';
  return null;
}

const requestedField = detectRequestedField(message);

let matchedMemory = null;

// If a new attachment is uploaded, skip memory cache so the new file gets processed freshly
if (!hasNewAttachment) {
  for (let i = history.length - 1; i >= 0; i--) {
    const h = history[i];
    const issueSummary = (h.issue_summary || '').toLowerCase();
    const attachmentSummary = (h.attachment_summary || '').toLowerCase();
    const assistantMessage = (h.assistant_message || '').toLowerCase();
    const userQuery = (h.user_query || '').toLowerCase();
    const userMessage = (h.user_message || '').toLowerCase();
    const matchedIssue = (h.matched_issue || '').toLowerCase();

    if (matchedIssue !== 'attachment_info_request') continue;

    if (requestedField) {
      if (
        issueSummary.includes(requestedField) ||
        attachmentSummary.includes(requestedField) ||
        assistantMessage.includes(requestedField) ||
        userQuery.includes(requestedField) ||
        userMessage.includes(requestedField)
      ) {
        matchedMemory = h;
        break;
      }
    } else {
      matchedMemory = h;
      break;
    }
  }
}

return [{
  json: {
    ...$json,
    requested_field: requestedField,
    has_attachment_answer_in_memory: !!matchedMemory,
    attachment_answer_from_memory: matchedMemory
      ? (matchedMemory.assistant_message || matchedMemory.attachment_summary || matchedMemory.issue_summary || null)
      : null
  }
}];

