parameters.jsCode:
const item = $input.first().json;

const reply =
  item.answer ||
  item.final_response_text ||
  item.data?.text ||
  item.apiPayload?.response ||
  '';

return [{
  json: {
    conversationId: item.conversationId || item.data?.conversationId || '',
    user_message: item.message || item.user_message || '',
    assistant_message: reply,
    user_query: item.message || item.user_message || '',
    intent: 'attachment_info_request',
    matched_issue: 'attachment_info_request',
    issue_summary: reply || item.attachment_summary || item.message || '',
    attachment_summary: item.attachment_summary || '',
    ticket_id: item.ticket_id || null,
    messageId: item.messageId || item.data?.messageId || '',
    file_url: item.file_url || null,
    file_type: item.file_type || null,
    file_name: item.file_name || null
  }
}];

const input = $input.first().json;
const body = input.body || input;

const text = String(body.text || '').trim();
const sender = body.sender || 'Unknown';
const conversationId = body.conversationId || body.sessionId || body.userId || body.sender || `conv_${Date.now()}`;
const history = Array.isArray(body.history) ? body.history : [];

const fileUrl = body.file_url || null;
const fileType = body.file_type || '';
const fileName = body.file_name || '';

const hasPdf = fileType === 'application/pdf' || fileName.toLowerCase().endsWith('.pdf');
const hasImage = fileType.startsWith('image/') || ['.png', '.jpg', '.jpeg', '.webp', '.gif'].some(ext => fileName.toLowerCase().endsWith(ext));
const hasAttachment = Boolean(fileUrl || hasPdf || hasImage);

return [{
  json: {
    sender,
    conversationId,
    message: text,
    history,
    file_url: fileUrl,
    file_type: fileType,
    file_name: fileName,
    hasPdf,
    hasImage,
    hasAttachment,
    messageId: body.messageId || '',
    timestamp: body.timestamp || new Date().toISOString(),
    callback_url: body.callback_url || 'http://127.0.0.1:8000/api/send-response'
  }
}];

const data = $input.first().json;
const normalizedText = (data.message || '').toLowerCase().trim().replace(/\s+/g, ' ');
const errorMatch = normalizedText.match(/\b(400|401|403|404|408|409|429|500|502|503|504)\b/);

let attachmentHint = 'none';
if (data.hasPdf) attachmentHint = 'pdf';
else if (data.hasImage) attachmentHint = 'image';

return [{
  json: {
    ...data,
    normalizedText,
    possibleErrorCode: errorMatch ? errorMatch[1] : null,
    attachmentHint,
    isEmptyMessage: !normalizedText && !data.hasAttachment
  }
}];

const item = $input.first().json;

const messagesRaw = item.messages || item.data?.messages || item.memory || item.chat_memory || [];
const memoryRows = Array.isArray(messagesRaw) ? messagesRaw : [];

function extractTicketId(text) {
  if (!text) return null;
  const match = String(text).match(/ticket[_\-\s]?id[:\s]+(ticket_[a-zA-Z0-9_-]+)/i);
  return match ? match[1] : null;
}

const historyFromDb = memoryRows.map(row => {
  const userText =
    row.role === 'user'
      ? (row.user_query || row.user_message || row.message_text || row.text || '')
      : '';

  const assistantText =
    row.role === 'assistant'
      ? (row.assistant_message || row.message_text || row.text || '')
      : '';

  const matchedIssue = row.matched_issue || null;
  const explicitTicketId = row.ticket_id || null;
  const textTicketId = extractTicketId(userText || assistantText);

  const trustedTicketId =
    matchedIssue === 'manual_ticket' ||
    matchedIssue === 'existing_ticket_reused' ||
    /support ticket/i.test(userText || assistantText) ||
    /ticket id/i.test(userText || assistantText)
      ? (explicitTicketId || textTicketId)
      : null;

  return {
    role: row.role || 'user',
    text: row.role === 'user' ? userText : assistantText,
    message: row.role === 'user' ? userText : assistantText,
    user_message: row.role === 'user' ? (row.user_message || row.user_query || row.message_text || '') : '',
    user_query: row.role === 'user' ? (row.user_query || row.user_message || row.message_text || '') : '',
    assistant_message: row.role === 'assistant' ? (row.assistant_message || row.message_text || '') : '',
    intent: row.intent || null,
    matched_issue: matchedIssue,
    issue_summary: row.issue_summary || null,
    attachment_summary: row.attachment_summary || null,
    ticket_id: trustedTicketId,
    file_url: row.file_url || null,
    file_type: row.file_type || null,
    file_name: row.file_name || null,
    created_at: row.created_at || null
  };
}).filter(x => x.user_message || x.assistant_message || x.attachment_summary);

const incomingHistory = Array.isArray(item.history) ? item.history : [];
const history = historyFromDb.length > 0 ? historyFromDb : incomingHistory;

let latestTicketEntry = null;
for (let i = history.length - 1; i >= 0; i--) {
  const h = history[i];
  if (
    h.ticket_id &&
    (h.matched_issue === 'manual_ticket' || h.matched_issue === 'existing_ticket_reused')
  ) {
    latestTicketEntry = h;
    break;
  }
}

return [{
  json: {
    ...item,
    history,
    chat_summary: item.chat_summary || item.data?.chat_summary || '',
    latest_ticket_id: latestTicketEntry ? latestTicketEntry.ticket_id : null,
    latest_ticket_message: latestTicketEntry ? (latestTicketEntry.user_message || latestTicketEntry.assistant_message || latestTicketEntry.text) : null,
    has_existing_ticket: !!latestTicketEntry
  }
}];

return [{
  json: {
    ...$json,
    apiPayload: {
      response: 'Please type your issue or upload a screenshot/PDF so I can help you.',
      sender: 'AI Assistant',
      category: 'empty_message',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

const llmOutput = $input.first().json;
const original = $('Merge Attachment Context').first().json;

const raw = llmOutput?.content?.parts?.[0]?.text || llmOutput?.text || llmOutput?.output || '';

let cleaned = String(raw)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    intent: 'unclear',
    confidence: 0,
    error_code: null,
    needs_ocr: false,
    direct_reply: null,
    normalized_user_need: 'Could not parse model output',
    needs_ticket: true
  };
}

// Extract parsed_issue from combined LLM output if present
let parsedIssue = null;
if (parsed.matched_issue && parsed.matched_issue !== 'no_match') {
  parsedIssue = {
    matched_issue: parsed.matched_issue,
    short_resolution_or_hint: parsed.short_resolution_or_hint || '',
    confidence: parsed.kb_confidence || parsed.confidence || 0,
    needs_ticket: parsed.kb_needs_ticket || false
  };
}

const result = {
  ...original,
  parsed_intent: {
    intent: parsed.intent,
    confidence: parsed.confidence,
    error_code: parsed.error_code || null,
    needs_ocr: parsed.needs_ocr || false,
    direct_reply: parsed.direct_reply || null,
    normalized_user_need: parsed.normalized_user_need || '',
    needs_ticket: parsed.needs_ticket || false
  }
};

if (parsedIssue) {
  result.parsed_issue = parsedIssue;
}

return [{ json: result }];

const reply = $json.parsed_intent?.direct_reply || 'Hello! How can I help you today?';

return [{
  json: {
    ...$json,
    final_response_text: reply,
    final_category: 'greeting_or_ack',
    apiPayload: {
      response: reply,
      sender: 'AI Assistant',
      category: 'greeting_or_ack',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

return [{
  json: {
    ...$json,
    apiPayload: {
      response: "I'm sorry, I can only help with support-related issues such as loan queries, repayment problems, account access, and technical issues. Please describe a specific issue you're facing and I'll do my best to assist you.",
      sender: 'AI Assistant',
      category: 'gibberish',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

const item = $input.first().json;

