function stripEscalation(text) {
  if (!text) return text;
  return text
    .replace(/\s*if\s+(this|it|the issue)\s+(still\s+)?(doesn'?t|does not|hasn'?t|has not)\s+resolve[^.?!]*[.?!]?/gi, '')
    .replace(/\s*would you like me to (raise|escalate|create|log|contact|connect)[^.?!]*[.?!]?/gi, '')
    .replace(/\s*just\s+say\s+["']?contact support["']?[^.?!]*[.?!]?/gi, '')
    .replace(/\s*i will (log|escalate|raise|create|forward|contact|connect)[^.?!]*[.?!]?/gi, '')
    .replace(/\s*i('ll|\s+will)\s+(escalate|raise|create|forward|log|contact)[^.?!]*[.?!]?/gi, '')
    .replace(/\s*you can (say|type|write)\s+["']?(contact support|escalate)["']?[^.?!]*[.?!]?/gi, '')
    .replace(/\s*our (support |technical )?team\s+will\s+(look into|investigate|review)[^.?!]*[.?!]?/gi, '')
    .trim();
