    },

    followupTicketPayload: {
      ticket_id: latestTicketId,
      title: 'Follow-up on Existing Support Ticket',
      description: mergedDescription,
      latest_user_message: userMessage,
      previous_ticket_description: latestTicketMessage,
      category: 'followup_support',
      status: 'existing_ticket_followup',
      assigned_to: assignedTo,
      assigned_to_name: assignedToName,
      conversationId,
      created_from_conversation: conversationId,
      escalation_level: $json.ticketPayload?.escalation_level || 0,
      priority: 'Medium',
      created_at: new Date().toISOString(),
      chat_summary: $json.chat_summary || ''
    }
  }
}];

return $input.all().map(item => {
  const t = item.json.followupTicketPayload || item.json;

  return {
    json: {
      ...item.json,
      id: t.ticket_id || item.json.ticket_id || '',
      title: t.title || 'Follow-up on Existing Support Ticket',
      description: t.description || t.latest_user_message || '',
      priority: t.priority || 'Medium',
      status: t.status || 'existing_ticket_followup',
      assigned_to: t.assigned_to || 'support_team',
      assigned_to_name: t.assigned_to_name || 'Support Team',
      created_at: t.created_at || new Date().toISOString(),
      updated_at: new Date().toISOString(),
      escalation_level: t.escalation_level || 0,
      category: t.category || 'followup_support',
      conversationId: t.conversationId || item.json.conversationId || '',

      teamsPayload: {
        "@type": "MessageCard",
        "@context": "http://schema.org/extensions",
        "summary": `Follow-up on ticket: ${t.ticket_id || ''}`,
        "themeColor": "FFA500",
        "title": "Ticket Follow-Up",
        "text": `CHAT_CONVERSATION_ID: ${t.conversationId || item.json.conversationId || 'N/A'}`,
        "sections": [
          {
            "facts": [
              { "name": "Ticket ID", "value": t.ticket_id || item.json.ticket_id || '' },
              { "name": "Title", "value": t.title || 'Follow-up on Existing Support Ticket' },
              { "name": "Previous Ticket Description", "value": t.previous_ticket_description || 'N/A' },
              { "name": "Latest User Follow-Up", "value": t.latest_user_message || item.json.message || 'N/A' },
              { "name": "Merged Description", "value": t.description || 'N/A' },
              { "name": "Assigned To", "value": t.assigned_to_name || 'Support Team' },
              { "name": "Status", "value": t.status || 'existing_ticket_followup' },
              { "name": "Chat Summary", "value": t.chat_summary || item.json.chat_summary || 'No summary available' }
            ]
          }
        ]
      }
    }
  };
});

return $input.all().map(item => {
  return {
    json: {
      ...item.json,
      new_ticket_created: true,
      created_ticket_id: item.json.ticket_id || item.json.id || null
    }
  };
});

