parameters.jsCode:
return [{
  json: {
    conversationId: $json.conversationId || '',
    user_message: $json.message || '',
    assistant_message: $json.attachment_answer_from_memory || '',
    user_query: $json.message || '',
    intent: 'attachment_info_request',
    matched_issue: 'attachment_info_request',
    issue_summary: $json.attachment_answer_from_memory || $json.message || '',
    attachment_summary: $json.attachment_summary || '',
    ticket_id: null,
    messageId: $json.messageId || ''
  }
}];

const source = $('Prepare Ticket Ack').first().json;

const ticketId = source.final_ticket_id || source.ticket_create_response?.ticket_id || '';
const ticketTitle = source.ticketPayload?.ticket_title || 'Support Ticket';
const ticketDescription = source.ticketPayload?.ticket_description || source.originalMessage || '';
const assignedToName = source.assigned_to_name || 'Support Team';
const priority = source.ticketPayload?.priority || 'Medium';
const conversationId = source.conversationId || '';
const category = source.ticketPayload?.category || 'manual_ticket';
const chatSummaryRaw = source.ticketPayload?.chat_summary || source.chat_summary || '';

// Fallback: build summary from history + current message if chat_summary is empty
let chatSummary = chatSummaryRaw;
if (!chatSummary) {
  const parts = [];
  const history = Array.isArray(source.history) ? source.history : [];
  for (const h of history) {
    if (h.role === 'user' && (h.user_message || h.user_query)) {
      parts.push('USER: ' + (h.user_message || h.user_query));
    } else if (h.role === 'assistant' && h.assistant_message) {
      parts.push('ASSISTANT: ' + h.assistant_message);
    }
  }
  if (source.originalMessage) {
    parts.push('USER (current): ' + source.originalMessage);
  }
  if (source.final_response_text) {
    parts.push('ASSISTANT (current): ' + source.final_response_text);
  }
  chatSummary = parts.length > 0 ? parts.join('\n') : 'No summary available';
}

return [{
  json: {
    ...source,
    teamsPayload: {
      "@type": "MessageCard",
      "@context": "http://schema.org/extensions",
      "summary": "New Support Ticket: " + ticketId,
      "themeColor": "0076D7",
      "title": "New Support Ticket Created",
      "text": "CHAT_CONVERSATION_ID: " + conversationId,
      "sections": [
        {
          "facts": [
            { "name": "Ticket ID", "value": ticketId },
            { "name": "Title", "value": ticketTitle },
            { "name": "Description", "value": ticketDescription },
            { "name": "Priority", "value": priority },
            { "name": "Category", "value": category },
            { "name": "Assigned To", "value": assignedToName },
            { "name": "Status", "value": "Open" },
            { "name": "Chat Summary", "value": chatSummary || 'No summary available' }
          ]
        }
      ]
    }
  }
}];

const raw = ($json.normalizedText || $json.message || '').toLowerCase().trim().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ');

// Collapse runs of 3+ identical consecutive chars down to 2
// "hiiiiiiiiiiiiieeeeeeeeee" -> "hiiee"
// "hellooooo" -> "helloo"
// "thankssss" -> "thankss"
const msg = raw.replace(/(.)\1{2,}/g, '$1$1');

// Greeting patterns
const greetingPatterns = [
  /^h+e+l+o+$/,
  /^h+e+l+l+o+$/,
  /^h+i+$/,
  /^h+i+e*$/,
  /^h+e+y+$/,
  /^h+i+y+a*$/,
  /^y+o+$/,
  /^s+u+p+$/,
  /^h+o+w+d+y+$/,
  /^good\s*(morning|evening|afternoon|night|day)$/,
  /^(gm|gn|ge)$/,
  /^whats\s*up$/,
  /^wassup$/,
  /^wazzup$/,
  /^hola$/,
  /^greetings$/,
  /^namaste$/
];

// Acknowledgement patterns
const ackPatterns = [
  /^(ok|okay|okk+|k+|kk+)$/,
  /^(thanks|thankyou|thank\s*you|thx|ty|tysm|thanx)$/,
  /^(cool|nice|great|awesome|perfect|alright|aight|got\s*it|noted|sure|fine|np|no\s*problem|welcome|no\s*worries)$/,
  /^(yes|yeah|yep|yup|ya|yaa+|nope|no|nah)$/,
  /^(bye|goodbye|good\s*bye|see\s*you|see\s*ya|later|cya|ttyl|take\s*care)$/
];

// Personal intro patterns (not a support issue)
const introPatterns = [
  /^(my\s*name\s*is|im|i\s*am|this\s*is)\s+[a-z]+$/,
  /^(im|i\s*am)\s+from\s+[a-z]+$/
];

let isGreeting = false;
let directReply = null;

for (const p of greetingPatterns) {
  if (p.test(msg)) {
    isGreeting = true;
    directReply = 'Hello! How can I help you today?';
    break;
  }
}

if (!isGreeting) {
  for (const p of ackPatterns) {
    if (p.test(msg)) {
      isGreeting = true;
      if (/thanks|thankyou|thank\s*you|thx|ty|tysm|thanx/.test(msg)) {
        directReply = "You're welcome! Let me know if you need anything else.";
      } else if (/bye|goodbye|good\s*bye|see\s*you|see\s*ya|later|cya|ttyl|take\s*care/.test(msg)) {
        directReply = 'Goodbye! Feel free to reach out anytime.';
      } else {
        directReply = 'Alright! Let me know if there is anything else I can help with.';
      }
      break;
    }
  }
}

if (!isGreeting) {
  for (const p of introPatterns) {
    if (p.test(msg)) {
      isGreeting = true;
      directReply = 'Nice to meet you! How can I help you today?';
      break;
    }
  }
}

return [{
  json: {
    ...$json,
    is_regex_greeting: isGreeting,
    regex_greeting_reply: directReply,
    parsed_intent: isGreeting ? {
      intent: 'greeting_or_ack',
      confidence: 1.0,
      error_code: null,
      needs_ocr: false,
      direct_reply: directReply,
      normalized_user_need: 'Greeting or acknowledgement',
      needs_ticket: false
    } : ($json.parsed_intent || null)
  }
}];

const msg = ($json.normalizedText || $json.message || '').toLowerCase().trim();
const possibleErrorCode = $json.possibleErrorCode || null;
const history = Array.isArray($json.history) ? $json.history : [];
const hasAttachment = $json.hasAttachment || false;

let detectedIntent = null;
let directReply = null;
let errorCode = null;
let normalizedNeed = null;
let needsTicket = false;
let parsedIssue = null;

// --- ERROR CODE (skip both LLMs) ---
if (possibleErrorCode) {
  const errorKbMap = {
    '400': { matched_issue: 'Invalid request parameters', short_resolution_or_hint: 'Please ensure all required fields are included in your request.', confidence: 0.95, needs_ticket: false },
    '401': { matched_issue: '401 Unauthorized', short_resolution_or_hint: 'Authentication failed. Please check your API keys, tokens, or login credentials.', confidence: 0.95, needs_ticket: false },
    '403': { matched_issue: '403 Forbidden', short_resolution_or_hint: 'Access to the resource is denied. Please ensure you have the proper permissions.', confidence: 0.95, needs_ticket: false },
    '404': { matched_issue: '404 Not Found', short_resolution_or_hint: 'The requested resource or endpoint does not seem to exist. Please verify the URL or webhook path.', confidence: 0.95, needs_ticket: false },
    '408': { matched_issue: 'Repayment gateway timeout', short_resolution_or_hint: 'The request timed out. Please retry the operation.', confidence: 0.9, needs_ticket: false },
    '429': { matched_issue: 'API request returning error', short_resolution_or_hint: 'Too many requests. Please wait a moment and try again.', confidence: 0.9, needs_ticket: false },
    '500': { matched_issue: '500 Internal Server Error', short_resolution_or_hint: 'The server encountered an unexpected error. Please check backend logs for details.', confidence: 0.95, needs_ticket: false },
    '502': { matched_issue: 'API request returning error', short_resolution_or_hint: 'Bad gateway error. The upstream server returned an invalid response.', confidence: 0.9, needs_ticket: false },
    '503': { matched_issue: '503 Service Unavailable', short_resolution_or_hint: 'The service is temporarily unavailable. Please retry after some time.', confidence: 0.95, needs_ticket: false },
    '504': { matched_issue: 'Repayment gateway timeout', short_resolution_or_hint: 'Gateway timeout. The server did not respond in time. Please retry.', confidence: 0.9, needs_ticket: false }
  };
  const kbMatch = errorKbMap[possibleErrorCode];
  if (kbMatch) {
    detectedIntent = 'error_code_issue';
    errorCode = possibleErrorCode;
    normalizedNeed = 'Error code ' + possibleErrorCode + ' reported';
    parsedIssue = kbMatch;
  }
}

// --- FOLLOW-UP ---
if (!detectedIntent && !hasAttachment) {
  const followUpPatterns = [
    /^(still\s*(not\s*working|same|facing|having|getting|broken|failing|pending|waiting|stuck))/,
    /^(same\s*(issue|error|problem|thing))/,
    /^(not\s*(resolved|fixed|working|done)\s*(yet|still)?)/,
    /^(did\s*you\s*(fix|resolve|check|look))/,
    /^(any\s*(update|progress|news|response))/,
    /^(update\s*(please|pls)?$)/,
    /^(what\s*now$)/,
    /^(no\s*(change|luck|update|progress))/,
    /^(it\s*(still|is\s*still)\s*(not|broken|failing|pending))/,
    /^(when\s*will\s*(this|it)\s*be\s*(fixed|resolved|done))/
  ];
  for (const p of followUpPatterns) {
    if (p.test(msg)) {
      detectedIntent = 'follow_up';
      normalizedNeed = 'Follow-up on previous issue';
      break;
    }
  }
}

// --- FOLLOWUP SUPPORT ---
if (!detectedIntent && !hasAttachment) {
  const followupSupportPatterns = [
    /contact\s*support/,
    /connect\s*(me\s*)?to\s*support/,
    /human\s*(support|agent)/,
    /talk\s*to\s*(support|agent|human|someone)/,
    /representative/,
    /real\s*person/,
    /customer\s*care/,
    /escalate/,
    /follow\s*up\s*(on\s*)?(my\s*)?(ticket|issue)/,
    /raise\s*this\s*again/,
    /please\s*(connect|contact|reach|escalate|follow)/,
    /ask\s*the\s*support\s*team/,
    /check\s*with\s*(the\s*)?support/
  ];
  for (const p of followupSupportPatterns) {
    if (p.test(msg)) {
      detectedIntent = 'followup_support';
      normalizedNeed = 'User requesting support team follow-up or escalation';
      break;
    }
  }
}

// --- ISSUE RECALL ---
if (!detectedIntent) {
  const recallPatterns = [
    /what\s*(did\s*i\s*ask|was\s*my\s*(issue|problem|error|question))/,
    /what\s*(issue|error|problem)\s*did\s*i/,
    /remind\s*me\s*(the\s*)?(issue|error|problem)/,
    /what\s*did\s*(you|i)\s*say\s*(earlier|before|previously)/,
    /what\s*was\s*(the|its)\s*(solution|answer|response|fix)/,
    /did\s*i\s*ask\s*(about|something|anything)/,
    /what\s*was\s*the\s*thing\s*i\s*asked/
  ];
  for (const p of recallPatterns) {
    if (p.test(msg)) {
      detectedIntent = 'issue_recall';
      normalizedNeed = 'User recalling a previous question or issue';
      break;
    }
  }
}

// --- Build output ---
const hasRegexIntent = !!detectedIntent;
const result = {
  ...$json,
  has_regex_intent: hasRegexIntent,
  regex_detected_intent: detectedIntent
};

if (hasRegexIntent) {
  result.parsed_intent = {
    intent: detectedIntent,
    confidence: 0.95,
    error_code: errorCode,
    needs_ocr: false,
    direct_reply: directReply,
    normalized_user_need: normalizedNeed || msg,
    needs_ticket: needsTicket
  };
  if (parsedIssue) {
    result.parsed_issue = parsedIssue;
  }
}

return [{ json: result }];

// Cooldown disabled for back-and-forth support conversation feature.
// All follow-ups are allowed through immediately.
return [{
  json: {
    ...$json,
    followup_within_cooldown: false,
    followup_hours_remaining: 0
  }
}];

const ticketId = $json.latest_ticket_id || '';

let response = "Kindly wait for sometime, we'll get back to you as soon as possible.";

return [{
  json: {
    ...$json,
    final_response_text: response,
    final_category: 'followup_cooldown',
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category: 'followup_cooldown',
      conversationId: $json.conversationId || '',
      originalMessageId: $json.messageId || null,
      ticket_id: ticketId
    }
  }
}];
